Exception illegal = new IllegalArgumentException('illegal');
System.assertEquals('System.IllegalArgumentException', illegal.getTypeName());
Exception header = new InvalidHeaderException('header');
System.assertEquals('System.InvalidHeaderException', header.getTypeName());
Exception invalid = new InvalidParameterValueException('invalid');
System.assertEquals('System.InvalidParameterValueException', invalid.getTypeName());
invalid.setMessage('changed invalid');
System.assertEquals('changed invalid', invalid.getMessage());
System.assertEquals(0, invalid.getInaccessibleFields().size());
System.assertEquals(0, invalid.getLineNumber());
System.assertEquals('', invalid.getStackTraceString());
System.assertEquals(invalid, invalid.initCause(new QueryException('invalid cause')));
System.assertEquals('invalid cause', invalid.getCause().getMessage());
Exception readOnly = new InvalidReadOnlyUserDmlException('read only');
System.assertEquals('System.InvalidReadOnlyUserDmlException', readOnly.getTypeName());
readOnly.setMessage('changed read only');
System.assertEquals('changed read only', readOnly.getMessage());
System.assertEquals(0, readOnly.getInaccessibleFields().size());
System.assertEquals(0, readOnly.getLineNumber());
System.assertEquals('', readOnly.getStackTraceString());
System.assertEquals(readOnly, readOnly.initCause(new QueryException('read only cause')));
System.assertEquals('read only cause', readOnly.getCause().getMessage());
Exception noAccess = new NoAccessException('blocked', new Exception('root'));
Exception noData = new NoDataFoundException('missing', new Exception('root'));
Exception npe = new NullPointerException('null value', new Exception('root'));
System.assertEquals('blocked', noAccess.getMessage());
System.assertEquals('missing', noData.getMessage());
System.assertEquals('null value', npe.getMessage());
System.assertEquals('root', noAccess.getCause().getMessage());
System.assertEquals('root', noData.getCause().getMessage());
System.assertEquals('root', npe.getCause().getMessage());

